begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
set local timezone='Pacific/Honolulu';
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at)
select ('a9000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','agenda-'||n||'@example.invalid','x',now(),now(),now() from generate_series(1,6) n;
insert into public.staff_users(user_id,role) values('a9000000-0000-4000-8000-000000000001','admin'),('a9000000-0000-4000-8000-000000000002','office'),('a9000000-0000-4000-8000-000000000003','technician'),('a9000000-0000-4000-8000-000000000004','technician');
insert into public.customers(id,name) values('c9000000-0000-4000-8000-000000000001','Klient Alfa'),('c9000000-0000-4000-8000-000000000002','Klient Beta');
insert into public.staff_customer_assignments(user_id,customer_id) values('a9000000-0000-4000-8000-000000000003','c9000000-0000-4000-8000-000000000001'),('a9000000-0000-4000-8000-000000000003','c9000000-0000-4000-8000-000000000002'),('a9000000-0000-4000-8000-000000000004','c9000000-0000-4000-8000-000000000001');
insert into public.customer_memberships(user_id,customer_id) values('a9000000-0000-4000-8000-000000000005','c9000000-0000-4000-8000-000000000001');
create function pg_temp.task(n integer,who integer default 3,delta integer default 0,state text default 'todo',client integer default 1) returns jsonb language sql as $$select public.save_crm_record(('c9000000-0000-4000-8000-'||lpad(client::text,12,'0'))::uuid,'tasks',('d9000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,null,jsonb_build_object('title',case when who=4 then 'HIDDEN OTHER TASK' else 'Działanie '||n end,'description','TASK DESCRIPTION','kind','follow_up','dueOn',to_char((now() at time zone 'Europe/Warsaw')::date+delta,'YYYY-MM-DD'),'assigneeId','a9000000-0000-4000-8000-'||lpad(who::text,12,'0'),'contactId',null,'state',state,'result',''))$$;
set local role authenticated;
select set_config('request.jwt.claim.sub','a9000000-0000-4000-8000-000000000002',true);
select pg_temp.task(n,3,-n) from generate_series(1,8) n;
select pg_temp.task(9,3,0),pg_temp.task(10,3,1),pg_temp.task(11,3,-1,'done'),pg_temp.task(12,3,-1,'cancelled'),pg_temp.task(13,4,-1),pg_temp.task(14,2,-1),pg_temp.task(15,1,0),pg_temp.task(16,3,-1,'todo',2);
select set_config('request.jwt.claim.sub','a9000000-0000-4000-8000-000000000003',true);
select is(public.my_task_alerts()->>'viewerId','a9000000-0000-4000-8000-000000000003','Projection uses caller identity');
select is(public.my_task_alerts()->>'today',public.my_crm_tasks()->>'today','Projection uses canonical Warsaw day');
select is(public.my_task_alerts()->'counts'->>'today','1','Only open today tasks counted');
select is(public.my_task_alerts()->'counts'->>'overdue','9','All overdue counted beyond preview cap');
select is(jsonb_array_length(public.my_task_alerts()->'items'),5,'Preview bounded to five');
select is(public.my_task_alerts()->'items'->0->>'title','Działanie 8','Oldest deadline first');
select is(public.my_task_alerts()->'items'->4->>'title','Działanie 4','Preview remains ordered by deadline');
select ok(public.my_task_alerts()::text !~ 'TASK DESCRIPTION|PRIVATE|HIDDEN|assigneeId|description|result|completedAt|updatedAt|email','Projection contains metadata only');
select ok(not exists(select 1 from jsonb_array_elements(public.my_task_alerts()->'items') i where i->>'dueOn'>public.my_task_alerts()->>'today' or i->>'state' not in('todo','in_progress')),'No future or closed preview tasks');
select is(public.my_task_alerts()->'counts'->>'overdue',public.my_crm_tasks('overdue')->>'total','Alert counts equal unsearched agenda');
select public.crm_task_progress('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000008',0,'done','PRIVATE RESULT');
select is(public.my_task_alerts()->'counts'->>'overdue','8','Completion decreases alert count');
select is(public.my_task_alerts()->'items'->0->>'title','Działanie 7','Preview fills gap after completion');
select public.crm_task_progress('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000009',0,'done','');
select is(public.my_task_alerts()->'counts'->>'today','0','Completion removes today alert');
select set_config('request.jwt.claim.sub','a9000000-0000-4000-8000-000000000002',true);
select is(public.my_task_alerts()->'counts'->>'overdue','1','Office counts personal tasks only');
select set_config('request.jwt.claim.sub','a9000000-0000-4000-8000-000000000001',true);
select is(public.my_task_alerts()->'counts'->>'today','1','Admin counts personal tasks only');
reset role;
delete from public.staff_customer_assignments where user_id='a9000000-0000-4000-8000-000000000003' and customer_id='c9000000-0000-4000-8000-000000000002';
set local role authenticated;
select set_config('request.jwt.claim.sub','a9000000-0000-4000-8000-000000000003',true);
select is(public.my_task_alerts()->'counts'->>'overdue','7','Revocation removes task from counts');
reset role;
update public.customers set archived_at=now() where id='c9000000-0000-4000-8000-000000000001';
set local role authenticated;
select is(public.my_task_alerts()->'counts'->>'overdue','0','Archived customers excluded');
select is(jsonb_array_length(public.my_task_alerts()->'items'),0,'Empty preview reflects true zero');
reset role;
insert into public.account_access(user_id,blocked) values('a9000000-0000-4000-8000-000000000003',true);
set local role authenticated;
select throws_ok($$select public.my_task_alerts()$$,'42501',null,'Blocked account denied');
select set_config('request.jwt.claim.sub','a9000000-0000-4000-8000-000000000005',true);
select throws_ok($$select public.my_task_alerts()$$,'42501',null,'Portal client denied');
select set_config('request.jwt.claim.sub','a9000000-0000-4000-8000-000000000006',true);
select throws_ok($$select public.my_task_alerts()$$,'42501',null,'No-role account denied');
reset role;
set local role anon;
select throws_ok($$select public.my_task_alerts()$$,'42501',null,'Anonymous execute denied');
select * from finish();
rollback;
